js:(async()=>{const H=(m,b)=>({method:m,headers:{Authorization:'Bearer '+localStorage.getItem('erp_token'),'Content-Type':'application/json'},body:b?JSON.stringify(b):undefined});const J=(m,p,b)=>fetch('/api'+p,H(m,b)).then(async(r)=>({s:r.status,b:await r.json().catch(()=>null)}));
const ex=(await J('GET','/items')).b;
const dbg=[];const mk=async(code,cat)=>{const old=ex.find(x=>x.code===code);if(old)return old;const r=await J('POST','/items',{code,name:'QA재고1-'+code,unit:'EA',category:cat,unitPrice:0,safetyStock:0});dbg.push('item'+r.s+(r.s>=400?JSON.stringify(r.b).slice(0,80):''));return r.b};
const p=await mk('QAM17P','FINISHED'),a=await mk('QAM17A','RAW_MATERIAL'),b=await mk('QAM17B','RAW_MATERIAL');
for(const x of (await J('GET','/productions')).b.filter(x=>x.productId===p.id)){await J('DELETE','/productions/'+x.id)}for(const x of (await J('GET','/work-orders')).b.filter(x=>x.productId===p.id)){await J('DELETE','/work-orders/'+x.id)}for(const x of (await J('GET','/boms?versions=all')).b.filter(x=>x.productId===p.id)){await J('DELETE','/boms/'+x.id)}const wh=(await J('GET','/warehouses')).b.find(w=>w.code==='QA-WH');
await J('POST','/stock/transactions',{itemId:a.id,warehouseId:wh.id,type:'INBOUND',quantity:100,unitPrice:0});
await J('POST','/stock/transactions',{itemId:b.id,warehouseId:wh.id,type:'INBOUND',quantity:100,unitPrice:0});
const sd=(await J('GET','/stock')).b;const bq=(id)=>Number(sd.filter(r=>r.itemId===id&&r.warehouseId===wh.id).reduce((t,r)=>t+Number(r.quantity),0));sessionStorage.setItem('m17b',JSON.stringify([bq(a.id),bq(b.id),bq(p.id)]));const bom=(await J('POST','/boms',{productId:p.id,lines:[{componentId:a.id,quantity:2},{componentId:b.id,quantity:1}]})).b;
const wo=(await J('POST','/work-orders',{productId:p.id,warehouseId:wh.id,plannedQty:10})).b;
const pr=await J('POST','/productions',{workOrderId:wo.id,producedQty:10});dbg.push('wo'+JSON.stringify(wo).slice(0,60),'pr'+pr.s+JSON.stringify(pr.b).slice(0,100));sessionStorage.setItem('m17dbg',dbg.join(';'));if(pr.s>=300)throw new Error(dbg.join(';'));
sessionStorage.setItem('m17',JSON.stringify({p:p.id,a:a.id,b:b.id,wh:wh.id,wo:wo.id,bom:bom.id,pr:pr.s}));return true})()
